@@ -0,0 +1,17 @@
+import { createServer } from "node:http";
+import { fetchWebhook } from "../../targets/webhook-service";
+
+// Exploit PoC for CVE-2026-XXXX (SSRF via redirect to link-local metadata address). Patched in webhook-service 2.4.1.
+// This test must keep failing the exploit: the patched code has to reject the payload.
+const PAYLOADS = [
+  "http://169.254.169.254/latest/meta-data/iam/security-credentials/",
+  "http://127.0.0.1:9999/admin",
+  "http://[::ffff:7f00:1]/admin",
+];
+
+test.each(PAYLOADS)("exploit payload %s is rejected", async (payload) => {
+  const server = createServer((_req, res) => { res.writeHead(302, { location: payload }); res.end(); }).listen(0, "127.0.0.1");
+  const { port } = server.address() as { port: number };
+  await expect(fetchWebhook(`http://127.0.0.1:${port}/hook`)).rejects.toThrow(/blocked address/);
+  server.close();
+});
